SourceCode.Declaration:
/// <summary>
/// Parallel create-trans worker for ONE deal bucket and ONE transaction type.
/// Runs create-trans inline (maxBatchTaskNum = 1) so it never nests a further split.
/// Posting is deliberately NOT done here — it is a separate single-threaded task,
/// because rebate posting writes to shared ledger / subledger / voucher number
/// sequences that are not partitioned by deal and cannot run concurrently.
/// </summary>
internal final class METRebateCreateTask extends RunBaseBatch implements BatchRetryable
{
    private container dealRecIds;
    private TAMRebateTransactionType rebateTransactionType;
    private TAMRebateFromDate fromDate;
    private TAMRebateToDate toDate;

    #DEFINE.CurrentVersion(1)

}

Method.Source:
internal static METRebateCreateTask construct(
    TAMRebateTransactionType _type,
    container _dealRecIds,
    TAMRebateFromDate _f,
    TAMRebateToDate _t)
{
    METRebateCreateTask task = new METRebateCreateTask();
    task.rebateTransactionType = _type;
    task.dealRecIds = _dealRecIds;
    task.fromDate = _f;
    task.toDate = _t;

    return task;
}

public void run()
{
    METRebateCombinedFlow::createTrans(rebateTransactionType, dealRecIds, fromDate, toDate);
}

public container pack()
{
    return [#CurrentVersion, dealRecIds, rebateTransactionType, fromDate, toDate];
}

public boolean unpack(container _p)
{
    Integer version = conPeek(_p, 1);
    if (version != #CurrentVersion)
    {
        return false;
    }

    [version, dealRecIds, rebateTransactionType, fromDate, toDate] = _p;

    return true;
}

public ClassDescription caption()
{
    return strFmt("Rebate create transactions (%1)", enum2str(rebateTransactionType));
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
